    .replace(/\b(?:es|seria|sera|son) (?:un |una )?(?:tratamiento|procedimiento|producto|relleno)s? (?:muy |bien |tan )?(?:agresiv\w*|invasiv\w*|abusiv\w*)\b/g, ' ')
    .replace(/\bno quiero abusar de (?:tu|su) (?:tiempo|paciencia|amabilidad)\b/g, ' ')
