    baja: e.baja === true,
    derivado: e.derivado === true,
    pedidos: Number.isFinite(e.pedidos) && e.pedidos > 0 ? Math.min(Math.floor(e.pedidos), 5) : 0,
    reintentos: Number.isFinite(e.reintentos) && e.reintentos > 0 ? Math.min(Math.floor(e.reintentos), 5) : 0,
