  if (!/^https:\/\/[^\s]+$/i.test(String(url))) return cmTexto(cuerpo);
  return Object.assign(cmBase('interactive'), { interactive: {
    type: 'cta_url', body: { text: cmRecorte(cuerpo, 1024) },
