  const t = cnTextoDeGemini(j).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  if (!t) return null;
  const m = /\{[\s\S]*\}/.exec(t);
  try {
    const o = JSON.parse(m ? m[0] : t);
    return o && typeof o === 'object' && !Array.isArray(o) ? o : null;
  } catch (e) {
    return null;
  }
}
// La clave de la ficha es el teléfono de origen y solo dígitos: nunca un nombre que toque el prototipo.
function cnClaveValida(from) {
  return /^\d{6,20}$/.test(String(from || ''));
}
// Las fichas de los teléfonos (`staticData.global.doctoras`). Un nodo que SOLO LEE no escribe nada en los datos estáticos.
function cnMapaDeFichas(escribir) {
  let sd = null;
  try { sd = $getWorkflowStaticData('global'); } catch (e) { sd = null; }
  if (!sd) return { sd: null, mapa: {} };
  const valido = sd.doctoras && typeof sd.doctoras === 'object' && !Array.isArray(sd.doctoras);
  if (!valido) {
    if (escribir !== true) return { sd: sd, mapa: {} };
    sd.doctoras = {};
  }
  return { sd: sd, mapa: sd.doctoras };
}
function cnFichaDe(mapa, from) {
  return cnClaveValida(from) && Object.prototype.hasOwnProperty.call(mapa, from) ? mapa[from] : null;
}
// La atención del teléfono: lo que devolvió la ingesta del entrante si lo trae, y si no, lo que dijo `configuracionFlujo`. Ante la duda, normal.
function cnAtencion(rIngesta, cfg) {
  const a = rIngesta && typeof rIngesta === 'object' && rIngesta.atencion && typeof rIngesta.atencion === 'object'
    ? rIngesta.atencion : null;
  const estados = ['normal', 'operador', 'bloqueado'];
  const estado = a && estados.indexOf(a.estado) >= 0 ? a.estado
    : (estados.indexOf(cfg.atencionEstado) >= 0 ? cfg.atencionEstado : 'normal');
  const avisarIngesta = rIngesta && typeof rIngesta === 'object' ? rIngesta.avisarRecepcion : '';
  const avisarCfg = a && a.avisarRecepcion !== undefined ? a.avisarRecepcion : cfg.atencionAvisarRecepcion;
  const avisar = ['operador', 'bloqueado'].indexOf(avisarIngesta || avisarCfg) >= 0 ? (avisarIngesta || avisarCfg) : '';
  return {
    estado: estado,
    avisar: avisar,
    mensajeFijo: String((a && a.mensajeFijo) || cfg.atencionMensajeFijo || '').trim(),
    respuestas: Number(a && a.respuestasEnVentana !== undefined ? a.respuestasEnVentana : cfg.atencionRespuestas) || 0,
    venceEn: String((a && a.ventanaVenceEn) || cfg.atencionVenceEn || ''),
  };
}

// ARMAR AVISOS: el aviso a la RECEPCIÓN (el WhatsApp de recepción de la doctora) con el MOTIVO exacto, por TEXTO LIBRE o por PLANTILLA UTILITY según la ventana de servicio de Meta.
//
//   - SOLO con el CONSENTIMIENTO de la persona (`ficha.consentimiento === 'si'`): sin «Sí, que me escriban» no hay aviso ni plantilla.
//   - DENTRO de 23,5 h del ÚLTIMO mensaje que la recepción (el número de `numeroRecepcion`) le escribió al bot: texto libre. Ese instante es `ultimoMs` de SU ficha (clave = su número).
//   - FUERA de esa ventana: PLANTILLA UTILITY (4 variables: nombre, motivo o interés, horario, teléfono). El nombre, el idioma y el estado son DATO de «Config base» (`drPlantilla`): si falta, o el estado no
//     es APPROVED, NUNCA se inventa; no sale nada («plantilla_no_configurada») y «Armar mensajes» le dice la verdad a la persona, con el botón. Sin ventana de 24 h no se envía texto libre.
//   - Quién avisa: la solicitud de valoración terminada, una consulta médica o un documento de salud (el aviso lleva SOLO «consulta médica», nunca lo que la persona escribió ni el documento) y lo que el
//     asistente no supo responder. La pausa por persona (`bloqueado`), la baja y el riesgo NO avisan.
//   - A lo más UN aviso por teléfono Y POR MOTIVO cada 30 minutos (`avisosConsulta` de la ficha; «Armar mensajes» lo fija solo si el aviso SALIÓ).
//
// Todo texto pasa por `avLimpio` (sin enlaces, sin llaves, sin palabras prohibidas, con tope). La salida SIEMPRE dice qué pasó (`planeado`, `repetido`, `clave`, `motivoFallo`): «Armar mensajes» decide con eso
// si puede decir «ya le avisé». En modo prueba el aviso va al teléfono de prueba, nunca a la recepción. Un destinatario igual a quien escribe se descarta (`avDestinatarios`).
const cfg = cnCfg();
const base = cnPrimero('Config base') || {};
const datos = drDatosVivos(base, cnPrimero('Traer configuración'));
const decision = cnPrimero('Decidir turno') || {};
const t = cnPrimero('Normalizar entrada') || {};
const from = String(decision.from || t.from || '');
const ahora = Number(t.ahoraMs) || Date.now();
const fichas = cnMapaDeFichas(false).mapa;
const fichaCliente = drFichaVigente(cnFichaDe(fichas, from), ahora);
const final = drResolver(decision, cnJsonDeGemini(cnPrimero('Conversar con el modelo')), fichaCliente, datos);
const plan = final.plan;

// 1. ¿Hay algo que avisar? Solo con consentimiento.
let aviso = null;
if (fichaCliente.consentimiento === 'si') {
  if (plan.tipo === 'derivado' && plan.aviso) aviso = plan.aviso;
  else if (plan.tipo === 'recepcion' && plan.aviso === true) aviso = { tipo: 'consulta', clave: plan.claveAviso, motivo: plan.motivo };
}
const clave = aviso && typeof aviso.clave === 'string' && DR_CLAVES_AVISO.indexOf(aviso.clave) >= 0 ? aviso.clave : '';
const sin = (extra) => [{ json: Object.assign({ sinAviso: true, plan: plan.tipo || '', planeado: false, repetido: false, clave: clave, motivoFallo: '' }, extra || {}) }];
if (!aviso || clave === '' || !cnClaveValida(from)) return sin();

// 2. Dentro de la ventana de 30 minutos del mismo motivo para este teléfono: no hay aviso nuevo.
const ultimoMotivo = fichaCliente.avisosConsulta[clave] || 0;
if (ultimoMotivo > 0 && ahora - ultimoMotivo >= 0 && ahora - ultimoMotivo < DR_VENTANA_AVISO_MS) return sin({ repetido: true });

// 3. El destinatario: la recepción (o el teléfono de prueba).
const prueba = cfg.modoPrueba === true;
let destinatarios = [];
if (prueba) {
  const tel = cnDigitos(cfg.telefonoDePrueba);
  if (tel) destinatarios = [{ rol: 'completo', tel: tel, nombre: '' }];
} else {
  destinatarios = avDestinatarios('completo:' + cnDigitos(cfg.numeroRecepcion), from, cfg.prefijosPermitidos, false);
}
if (!destinatarios.length) return sin({ motivoFallo: 'sin_destinatario' });

// 4. Los datos del aviso (el nombre y el horario los dio la persona; el interés es el tratamiento que miró).
const tr = fichaCliente.interes ? drTratamientoPorId(datos, fichaCliente.interes) : null;
const nombre = avLimpio(plan.tipo === 'derivado' ? fichaCliente.nombre : '', 60) || avPrimerNombre(t.nombrePerfil) || 'sin nombre';
const interes = tr ? avLimpio(tr.nombre, 40) : 'sin tratamiento definido';
const horario = plan.tipo === 'derivado' ? (avLimpio(plan.horario, 100) || 'sin horario') : 'sin horario';
const contacto = plan.tipo === 'derivado' && /^\d{8,15}$/.test(String(fichaCliente.contacto || '')) ? String(fichaCliente.contacto) : from;
const motivo = avLimpio(aviso.motivo, 100) || 'consulta';

// 5. La plantilla UTILITY: {{1}} nombre, {{2}} interés o motivo, {{3}} horario preferido, {{4}} teléfono. Cada variable es una sola línea (`avParametro`).
const solicitud = aviso.tipo === 'solicitud';
const parametros = [nombre, solicitud ? interes : motivo, horario, '+' + contacto];
const texto = avLimpio(solicitud
  ? 'Aviso del asistente: solicitud de valoración. Nombre: ' + nombre + '. WhatsApp: +' + contacto + '. Interés: ' + interes + '. Horario preferido: ' + horario + '. La persona aceptó que la contacten.'
  : 'Aviso del asistente: consulta de una persona que aceptó que la contacten. Motivo: ' + motivo + '. WhatsApp: +' + from + '. Respóndele directamente por WhatsApp.', 700);

const comun = { phoneNumberId: String(cfg.phoneNumberId || ''), waGraphVersion: cfg.waGraphVersion || 'v26.0', sinAviso: false, plan: plan.tipo || '', planeado: true, repetido: false, clave: clave, motivoFallo: '' };
const items = [];
for (const d of destinatarios) {
  const rec = drFichaVigente(cnFichaDe(fichas, d.tel), ahora);
  // La ventana de la recepción: su último mensaje al bot (la ficha con SU número). Sin ficha o con un reloj hacia atrás, está cerrada.
  const dentro = rec.ultimoMs > 0 && ahora - rec.ultimoMs >= 0 && ahora - rec.ultimoMs < DR_VENTANA_RECEPCION_MS;
  if (dentro) {
    if (!texto) continue;
    items.push({ json: Object.assign({}, comun, { para: d.tel, rol: d.rol, canal: 'texto', payload: avTexto(d.tel, texto) }) });
  } else {
    const pl = drPlantilla(base);
    const payload = pl ? avPlantilla(d.tel, pl.nombre, pl.idioma, parametros) : null;
    if (!payload) continue;
    items.push({ json: Object.assign({}, comun, { para: d.tel, rol: d.rol, canal: 'plantilla', payload: payload }) });
  }
}
return items.length ? items : sin({ motivoFallo: 'plantilla_no_configurada' });

// FUENTES DEL GUARDADO: las arma Flujos/experimental/comun-sin-agente/src/guardado.mjs para este flujo (nombres de nodo literales, para que n8n los precargue).
const GM_FUENTES = {
  carga: $('Carga de entrada').isExecuted ? $('Carga de entrada').first().json : {},
  config: $('Config del negocio').isExecuted ? $('Config del negocio').first().json : {},
};

// PREPARAR GUARDADO (módulo común de medios, contrato v2 «guardar y descargar TODO» del 30/10/2026 §1 y §4): decide si el medio de ESTE mensaje
// entrante se guarda y con qué cabeceras.
//
// Corre en su PROPIA rama, colgada de «Reportar mensaje (entrante)» (el servidor exige el entrante ya registrado por la ingesta) y DEBAJO de la rama que
// responde en el lienzo: con `executionOrder: v1` corre DESPUÉS de que el cliente recibió su respuesta, y nada de lo que pase acá corta el turno.
// Devuelve [] (la rama termina en silencio) si el mensaje no trae un medio, o si le falta un dato que el servidor exige.
// TODO medio se guarda (decisión de Andres, 30/10): imagen, audio (y nota de voz), video, documento de CUALQUIER tipo y sticker (va como `image`, webp).
// Ya no hay modo Anotar. Cada uno se baja con SU PROPIA descarga de Meta (no gasta el tope diario de ver u oír). El flujo NO se adelanta al tope por tipo
// del servidor (imagen 5 MB, audio, video y documento 16 MB): solo deja de bajar lo que Meta informa por encima de 16 MiB (`limite`), que cuenta como 413.
// `mime` es el que declara Meta SOLO si está en la lista cerrada de abajo; si no, `application/octet-stream` (el servidor decide por los bytes). Viaja en
// `X-NovuChat-Mime`. `contentType` (el transporte): imagen y audio, ese mismo mime; video y documento SIEMPRE `application/octet-stream`, para que el
// framework de la Function no intente parsear el cuerpo (un documento declarado application/json, form o multipart daría 400 antes del handler).
// También anota, en el estado estático del flujo (clave `guardadoDeMedios`), cuándo escribió por última vez la RECEPCIÓN: es la ventana de 24 h que
// decide si el aviso de falla puede salir como texto libre. Ningún dato del cliente se guarda ahí.
// Este nodo NO toca el binario: no lo hay todavía (se baja después) y nunca lo lee.
//
// `GM_FUENTES` la define la cabecera que arma `guardado.mjs` para cada flujo (`carga`: el nodo con `messages`; `config`: «Config del negocio»).
// JavaScript plano del nodo Code de n8n: sin require, URL, Buffer ni crypto.
const gmCarga = (GM_FUENTES && GM_FUENTES.carga && typeof GM_FUENTES.carga === 'object') ? GM_FUENTES.carga : {};
const gmCfg = (GM_FUENTES && GM_FUENTES.config && typeof GM_FUENTES.config === 'object') ? GM_FUENTES.config : {};
const gmMsg = Array.isArray(gmCarga.messages) && gmCarga.messages[0] && typeof gmCarga.messages[0] === 'object' ? gmCarga.messages[0] : null;
const gmAhora = Number(gmCarga.ahoraMs) > 0 ? Number(gmCarga.ahoraMs) : Date.now();
const gmSd = $getWorkflowStaticData('global');
if (!gmSd.guardadoDeMedios || typeof gmSd.guardadoDeMedios !== 'object' || Array.isArray(gmSd.guardadoDeMedios)) gmSd.guardadoDeMedios = {};
const gmEstado = gmSd.guardadoDeMedios;
if (!gmMsg) return [];

const gmTelefono = String(gmMsg.from || '');
const gmRecepcion = String(gmCfg.numeroRecepcionDigitos || gmCfg.numeroRecepcion || '').replace(/\D/g, '');
// La ventana de la recepción: su último mensaje a este número (de cualquier tipo).
if (gmRecepcion && gmTelefono === gmRecepcion) gmEstado.recepcionMs = gmAhora;

// El tipo del mensaje de WhatsApp → la categoría que se manda en `X-NovuChat-Tipo` (contrato v2 §1: image | audio | video | document).
const GM_TIPOS = { image: 'image', sticker: 'image', audio: 'audio', voice: 'audio', video: 'video', document: 'document' };
const gmTipoMeta = String(gmMsg.type || '');
const gmTipo = Object.prototype.hasOwnProperty.call(GM_TIPOS, gmTipoMeta) ? GM_TIPOS[gmTipoMeta] : '';
if (!gmTipo) return [];
const gmMedio = gmMsg[gmTipoMeta] || (gmTipo === 'audio' ? (gmMsg.audio || gmMsg.voice) : null);
if (!gmMedio || typeof gmMedio !== 'object') return [];
const gmMediaId = String(gmMedio.id || '');
const gmIdMeta = String(gmMsg.id || '');
// Lo que el servidor exige (§1): teléfono de 8 a 15 dígitos y el id del MENSAJE. Lo que viaja en una cabecera, sin espacios ni controles.
if (!/^\d{8,15}$/.test(gmTelefono) || !/^[\x21-\x7e]{1,200}$/.test(gmIdMeta) || !/^[A-Za-z0-9_-]{1,100}$/.test(gmMediaId)) return [];
const gmMimeCrudo = String(gmMedio.mime_type || '').toLowerCase().split(';')[0].trim();
// La lista CERRADA de mimes que viajan tal cual en `Content-Type`; cualquier otro (o uno de otra categoría) va como application/octet-stream.
const GM_MIMES = {
  image: ['image/jpeg', 'image/png', 'image/webp'],
  audio: ['audio/ogg', 'audio/opus', 'audio/mp4', 'audio/m4a', 'audio/x-m4a', 'audio/mpeg', 'audio/aac', 'audio/amr'],
  video: ['video/mp4', 'video/3gpp'],
  document: [
    'application/pdf', 'application/zip', 'text/plain', 'text/csv',
    'application/msword', 'application/vnd.ms-excel', 'application/vnd.ms-powerpoint',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    'application/vnd.openxmlformats-officedocument.presentationml.presentation',
