};
const gmMime = GM_MIMES[gmTipo].indexOf(gmMimeCrudo) >= 0 ? gmMimeCrudo : 'application/octet-stream';
const gmContentType = gmTipo === 'image' || gmTipo === 'audio' ? gmMime : 'application/octet-stream';
